BEGIN READ ONLY;
SET LOCAL statement_timeout='30s';
SELECT coalesce(json_agg(q),'[]'::json) FROM (
 SELECT id,topic_id,created_at,subject,message_id,length(body) AS body_length,left(body,12000) AS body
 FROM messages
 WHERE subject ~* '(^|[^[:alnum:]_])GIN([^[:alnum:]_]|$)'
 AND body ~* '(consistent.{0,80}(cache|memo)|(cache|memo).{0,80}consistent)'
 AND (body ILIKE '%consecutive%' OR body ILIKE '%adaptive%' OR body ILIKE '%cache miss%' OR body ILIKE '%hit rate%' OR body ILIKE '%miss rate%')
 ORDER BY created_at DESC,id DESC LIMIT 10
) q;
COMMIT;
